effect.shader:

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord

   /////////////////////////

    #define TAU 6.2831853071

    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 TanRyu;
        if (adaptive) { TanRyu = acScreenNorm; }
        else { 
        TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        TanRyu.y*=acLayerSize.y/acLayerSize.x;
        }

        TanRyu /= scale;
        TanRyu *= rot2m((0.0+angle)*0.0174533);
        TanRyu += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;


        /////////////////////////

    	vec4 result;

    	vec2 uv = TanRyu;

        float o = vec4(0.,0.,0., uv * 0.25 + vec2(0.0, progressa * 0.025)).r;
        float d = (texture2DCv(texx.texture, uv * 0.25 - vec2(0.0, progressa * 0.02 + o * 0.02)).r * 2.0 - 1.0);

        float v = uv.y + d * 0.1;
        v = 1.0 - abs(v * 2.0 - 1.0);
        v = pow(v, 2.0 + sin((progressa * 0.2 + d * 0.25) * TAU) * 0.5);

        vec3 color = vec3(0.0);

        float x = (1.0 - uv.x * 0.75);
        float y = 1.0 - abs(uv.y * progressc - 1.0);
        color += vec3(x * 0.5, y, x) * v;

        vec2 seed = TanRyu;
        vec2 r;
        r.x = fract(sin((seed.x * 12.9898) + (seed.y * 78.2330)) * 43758.5453);
        r.y = fract(sin((seed.x * 53.7842) + (seed.y * 47.5134)) * 43758.5453);

        float s = mix(r.x, (sin((progressa * 2.5 + 60.0) * r.y) * progressb + 0.5) * ((r.y * r.y) * (r.y * r.y)), 0.04); 
        color += pow(s, 70.0) * (1.0 - v);

        result.rgb = color;
        result.a = 1.0;

    	    // result
    	    // const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
            // vec4 gradmap;
            // float luminance = dot(result.rgb, luminanceWeighting);
            // gradmap = mix(color1,color2,luminance)*result.a;

    	// vec4 factor = mix(texColorX,gradmap,alpha);
    	vec4 factor = mix(texColorX,result,alpha);

        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            resultfinal = (factor * bright) * texColor.a;
        } else if( blendMode==1 ) {         // multiply
            factor *= bright;
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            factor *= bright;
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	gl_FragColor = resultfinal;
    }
